namespace ZoneEngine.Core.Thrak.Quests
{
    #region Usings ...

    using System;

    using AORebirth.Core.Entities;

    using SmokeLounge.AOtomation.Messaging.GameData;
    using SmokeLounge.AOtomation.Messaging.Messages.N3Messages;

    using Utility;

    using ZoneEngine.Core;

    #endregion

    /// <summary>
    /// Capture-backed Thrak garden-key QuestFullUpdate packets (20260718-185306).
    /// Patches recipient SimpleChar instance and mission expiry, then enqueues raw bytes.
    ///
    /// Timer: mission-window "Remain" is expiry - clientClock. Our GameTimeMessage anchors the
    /// client clock to ClientClockBaseSeconds (~Jan 2008). Unpatched 2026 capture expiries
    /// (0x6A83xxxx) therefore render as years of remaining time. Patch like PerkResetMissionSender /
    /// MissionAcceptService: expiry = clientClockNow + duration (capture duration 0xA8C0 = 12h).
    /// </summary>
    internal static class ThrakGardenKeyPacketSender
    {
        private const int CapturedCharacterInstance = unchecked((int)0x765A690A);
        private const int MissionIdentityType = 0x0000DAC3;

        /// <summary>Same GameTimeMessage epoch as MissionAcceptService / PerkResetMissionSender.</summary>
        private const long ClientClockBaseSeconds = 1_201_445_827L;

        /// <summary>Capture Unknown20/Unknown21 duration (0xA8C0 seconds = 12 hours).</summary>
        private const int MissionDurationSeconds = 12 * 60 * 60;

        private const string VeronicaQuestFullUpdateHex =
            "";

        private const string InsigniaQuestFullUpdateHex =
            "";

        private const string VeronicaUpdatedQuestFullUpdateHex =
            "";

        private const string GardenQuestFullUpdateHex =
            "";

        private const string SoulsQuestFullUpdateHex =
            "";

        private const string Souls1QuestFullUpdateHex =
            "";

        private const string Souls2QuestFullUpdateHex =
            "";

        private const string ReturnQuestFullUpdateHex =
            "";

        /// <summary>
        /// Capture Action59 for Mission:5556893A (character 765A690A). Mission instance bytes patched per quest.
        /// Wire Action is Int16=59. Do not use typed CharacterActionMessage (Action is Int32 for InfoRequest etc.).
        /// </summary>
        private const string CapturedAction59DeleteHex =
            "0135000A0001003700000DB6765A690A5E4777700000C350765A690A000000003B000000000000DAC35556893A0000DAC35556893A0000";

        /// <summary>Capture Quest/Delete for Mission:5556893A. Mission instance bytes patched per quest.</summary>
        private const string CapturedQuestDeleteHex =
            "0136000A0001003500000DB6765A690A212C487A0000C350765A690A0000000001000000000000DAC35556893A0000000000000000";

        private const int CapturedDeleteMissionInstance = unchecked((int)0x5556893A);

        internal static bool TrySendQuestFullUpdate(ICharacter character, string questId)
        {
            string hex = ResolveHex(questId);
            return !string.IsNullOrEmpty(hex) && TrySendRaw(character, hex);
        }

        /// <summary>
        /// Capture-backed journal delete. Same ordering as PerkResetMissionSender:
        /// enqueue typed Quest/Delete (and raw Action59+Delete hex) — never direct-send raw
        /// bytes, or they overtake a queued QuestFullUpdate and the client shows nothing.
        /// </summary>
        internal static bool TrySendQuestDelete(ICharacter character, string questId)
        {
            int instance;
            if (!TryResolveMissionInstance(questId, out instance) || !CanSend(character))
            {
                return false;
            }

            try
            {
                var client = (ZoneClient)character.Controller.Client;

                // Capture wire: Action59 (Int16) then Quest/Delete, mission instance patched.
                byte[] action59 = HexToBytes(CapturedAction59DeleteHex);
                ReplaceInstance(action59, CapturedCharacterInstance, character.Identity.Instance);
                ReplaceInstance(action59, CapturedDeleteMissionInstance, instance);
                byte[] questDelete = HexToBytes(CapturedQuestDeleteHex);
                ReplaceInstance(questDelete, CapturedCharacterInstance, character.Identity.Instance);
                ReplaceInstance(questDelete, CapturedDeleteMissionInstance, instance);
                client.EnqueueOutboundCompressedBuffer(action59);
                client.EnqueueOutboundCompressedBuffer(questDelete);

                // PerkReset path: typed Quest/Delete on the outbound queue.
                client.SendCompressed(
                    new QuestMessage
                    {
                        Identity = character.Identity,
                        Unknown = 0,
                        Action = QuestAction.Delete,
                        Unknown1 = 0,
                        Mission =
                            new Identity
                            {
                                Type = (IdentityType)MissionIdentityType,
                                Instance = instance
                            },
                        Unknown2 = 0,
                        Unknown3 = 0
                    });

                LogUtil.Debug(
                    DebugInfoDetail.Error,
                    "THRAK_GARDEN_KEY QuestDelete quest=" + questId
                    + " char=" + character.Identity.Instance.ToString("X8"));
                return true;
            }
            catch (Exception exception)
            {
                LogUtil.Debug(DebugInfoDetail.Error, "THRAK_GARDEN_KEY QuestDelete failed: " + exception.Message);
                return false;
            }
        }

        private static string ResolveHex(string questId)
        {
            if (string.IsNullOrWhiteSpace(questId))
            {
                return null;
            }

            if (string.Equals(questId, ThrakGardenKeyInteractionRules.QuestVeronica, StringComparison.OrdinalIgnoreCase))
            {
                return VeronicaQuestFullUpdateHex;
            }

            if (string.Equals(questId, ThrakGardenKeyInteractionRules.QuestInsignia, StringComparison.OrdinalIgnoreCase))
            {
                return InsigniaQuestFullUpdateHex;
            }

            if (string.Equals(questId, ThrakGardenKeyInteractionRules.QuestVeronicaUpdated, StringComparison.OrdinalIgnoreCase))
            {
                return VeronicaUpdatedQuestFullUpdateHex;
            }

            if (string.Equals(questId, ThrakGardenKeyInteractionRules.QuestGarden, StringComparison.OrdinalIgnoreCase))
            {
                return GardenQuestFullUpdateHex;
            }

            if (string.Equals(questId, ThrakGardenKeyInteractionRules.QuestSouls, StringComparison.OrdinalIgnoreCase))
            {
                return SoulsQuestFullUpdateHex;
            }

            if (string.Equals(questId, ThrakGardenKeyInteractionRules.QuestSouls1, StringComparison.OrdinalIgnoreCase))
            {
                return Souls1QuestFullUpdateHex;
            }

            if (string.Equals(questId, ThrakGardenKeyInteractionRules.QuestSouls2, StringComparison.OrdinalIgnoreCase))
            {
                return Souls2QuestFullUpdateHex;
            }

            if (string.Equals(questId, ThrakGardenKeyInteractionRules.QuestReturn, StringComparison.OrdinalIgnoreCase))
            {
                return ReturnQuestFullUpdateHex;
            }

            return null;
        }

        private static bool TryResolveMissionInstance(string questId, out int instance)
        {
            instance = 0;
            if (string.IsNullOrWhiteSpace(questId))
            {
                return false;
            }

            string normalized = questId.Trim();
            int colon = normalized.LastIndexOf(':');
            string hex = colon >= 0 ? normalized.Substring(colon + 1) : normalized;
            return int.TryParse(
                hex,
                System.Globalization.NumberStyles.HexNumber,
                System.Globalization.CultureInfo.InvariantCulture,
                out instance);
        }

        private static bool TrySendRaw(ICharacter character, string hex)
        {
            if (!CanSend(character) || string.IsNullOrWhiteSpace(hex))
            {
                return false;
            }

            try
            {
                var client = character.Controller.Client as ZoneClient;
                byte[] packet = HexToBytes(hex);
                ReplaceInstance(packet, CapturedCharacterInstance, character.Identity.Instance);
                PatchMissionExpiry(packet, client);
                client.EnqueueOutboundCompressedBuffer(packet);
                return true;
            }
            catch (Exception exception)
            {
                LogUtil.Debug(DebugInfoDetail.Error, "THRAK_GARDEN_KEY QuestFullUpdate failed: " + exception.Message);
                return false;
            }
        }

        /// <summary>
        /// Rewrite QuestActions[0].UnknownHash1 (AbsoluteTime expiry) so Remain matches duration.
        /// Capture values are in the 0x6A83xxxx band; each packet has exactly one such field.
        /// </summary>
        private static void PatchMissionExpiry(byte[] packet, ZoneClient client)
        {
            if (packet == null || client == null)
            {
                return;
            }

            double secondsSinceSync = (DateTime.UtcNow - client.LastGameTimeSyncUtc).TotalSeconds;
            if (secondsSinceSync < 0)
            {
                secondsSinceSync = 0;
            }

            if (secondsSinceSync > MissionDurationSeconds)
            {
                secondsSinceSync = 0;
                client.LastGameTimeSyncUtc = DateTime.UtcNow;
            }

            long clientClockNow = ClientClockBaseSeconds + (long)secondsSinceSync;
            long expiry = clientClockNow + MissionDurationSeconds;

            for (int i = 0; i + 4 <= packet.Length; i++)
            {
                int value = (packet[i] << 24)
                            | (packet[i + 1] << 16)
                            | (packet[i + 2] << 8)
                            | packet[i + 3];
                if ((value & unchecked((int)0xFFFF0000)) != 0x6A830000)
                {
                    continue;
                }

                WriteInt32BigEndian(packet, i, (int)expiry);
                return;
            }
        }

        private static void WriteInt32BigEndian(byte[] packet, int offset, int value)
        {
            packet[offset] = (byte)(value >> 24);
            packet[offset + 1] = (byte)(value >> 16);
            packet[offset + 2] = (byte)(value >> 8);
            packet[offset + 3] = (byte)value;
        }

        private static bool CanSend(ICharacter character)
        {
            return character != null
                   && character.Controller != null
                   && character.Controller.Client is ZoneClient;
        }

        private static void ReplaceInstance(byte[] packet, int from, int to)
        {
            byte f0 = (byte)(from >> 24);
            byte f1 = (byte)(from >> 16);
            byte f2 = (byte)(from >> 8);
            byte f3 = (byte)from;

            for (int i = 0; i + 4 <= packet.Length; i++)
            {
                if (packet[i] == f0 && packet[i + 1] == f1 && packet[i + 2] == f2 && packet[i + 3] == f3)
                {
                    packet[i] = (byte)(to >> 24);
                    packet[i + 1] = (byte)(to >> 16);
                    packet[i + 2] = (byte)(to >> 8);
                    packet[i + 3] = (byte)to;
                    i += 3;
                }
            }
        }

        private static byte[] HexToBytes(string hex)
        {
            int length = hex.Length / 2;
            byte[] bytes = new byte[length];
            for (int i = 0; i < length; i++)
            {
                bytes[i] = Convert.ToByte(hex.Substring(i * 2, 2), 16);
            }

            return bytes;
        }
    }
}
